const deathEdges = new WeakMap<World, Set<string>>();
/** 原生枪资格检查前关闭独立 roots；派生情侣关系不建立反向边。 */
export function expandWeddingDeaths(
  world: World,
  ids: number[],
  sources: DeathSources,
  eligibleDead: ReadonlySet<number>,
  nightOrigin?: Set<number>,
): Array<{ actorId: number; targetId: number }> {
  const b = bindings.get(world);
  if (!b) return [];
  if (b.status !== "complete" || !b.group || !validBinding(b))
    throw new Error("ghost_bride_relation_unavailable");
  const pairIds = [b.actorId, b.group.groomId],
    members = new Set(ids),
    roots = new Set(ids.filter((id) => (sources[id] ?? []).some((c) => c !== DeathCause.Lovers))),
    edges: Array<{ actorId: number; targetId: number }> = [],
    emitted = deathEdges.get(world) ?? new Set<string>();
  for (const root of pairIds) {
    if (!roots.has(root)) continue;
    const target = pairIds.find((id) => id !== root)!,
      p = b.participants.get(target)!;
    if (!sameBody(b, p, true) && !members.has(target) && !eligibleDead.has(target)) continue;
    if (!members.has(target)) {
      members.add(target);
      ids.push(target);
    }
    if (!(sources[target] ?? []).includes(DeathCause.Lovers))
      sources[target] = [...(sources[target] ?? []), DeathCause.Lovers];
    if (nightOrigin?.has(root)) nightOrigin.add(target);
    const key = `${root}:${target}`;
    if (!emitted.has(key)) {
      emitted.add(key);
      edges.push({ actorId: root, targetId: target });
    }
  }
  deathEdges.set(world, emitted);
  return edges;
}

export function weddingNightCapture(
  world: World,
  day: number,
): Readonly<WeddingKnifeCapture> | null {
  return bindings.get(world)?.nights.get(day)?.capture ?? null;
}

/** 重检双方原生命及原请求后，仅消耗一次已提交消息。 */
export function takeWeddingChat(
  scope: object,
): { actorId: number; recipientId: number; day: number; text: string } | null {
  const t = turns.get(scope),
    message = t?.chat;
  if (!t || !message || t.delivered) return null;
  const b = t.binding,
    setup = b.status !== "complete";
  if (
    b.pendingChat !== t ||
    !t.isCurrent() ||
    (setup && b.setupCurrent?.() !== true) ||
    !validBinding(b, setup) ||
    !validRequestProof(t) ||
    !targetCurrent(t, message.actorId) ||
    !targetCurrent(t, message.recipientId) ||
    (!setup && (!b.activeNight || b.activeNight.day !== t.day || b.activeNight.closed)) ||
    [...b.participants].some(([id, p]) => json(p.state) !== t.privateJson.get(id))
  ) {
    if (b.pendingChat === t) settleRequestDelivery(scope, false);
    return null;
  }
  t.delivered = true;
  b.pendingChat = null;
  if (setup) b.chats++;
  else b.activeNight!.chats++;
  settleRequestDelivery(scope, true);
  return { ...message };
}
/** 与原身份无关的最小关系投影；先复验绑定，canKnife 仍只是此时知识，见证人不接收聊天、票型或原生库存。 */
export function weddingActorView(world: World, actorId: number): WeddingActorView | null {
  const b = bindings.get(world);
  if (!b?.pair || b.status === "failed" || b.status === "cancelled") return null;
  if (!validBinding(b)) throw new Error("ghost_bride_authority_invalid");
  const n = b.activeNight,
    canKnife = !!n && n.capture.actorIds.includes(actorId) && validKnifeOwner(n);
  if (actorId === b.actorId || actorId === b.pair.groomId)
    return {
      policy: GHOST_BRIDE_POLICY,
      member: actorId === b.actorId ? "bride" : "groom",
      faction: Camp.ThirdParty,
      partnerId: actorId === b.actorId ? b.pair.groomId : b.actorId,
      witnessId: b.group?.witnessId ?? null,
      ...(actorId === b.pair.groomId && b.votes.length === 1
        ? { proposedWitnessId: b.votes[0]!.targetId }
        : {}),
      canKnife,
    };
  return actorId === b.group?.witnessId
    ? {
        policy: GHOST_BRIDE_POLICY,
        member: "witness",
        faction: Camp.ThirdParty,
        brideId: b.actorId,
        groomId: b.pair.groomId,
        canKnife,
      }
    : null;
}

/** 纯 preflight 与提交使用同一原体／请求目标证明。 */
export function canSubmitWeddingTool(
  world: World,
  actorId: number,
  phase: Phase,
  day: number,
  scope: object | undefined,
  value: unknown,
): boolean {
  const t = scope && turns.get(scope),
    call = readWeddingTool(value);
  if (
    !t ||
    !call ||
    call.name !== t.tool ||
    !authorizedWeddingTurn(world, actorId, phase, day, scope)
  )
    return false;
  if (call.name === "speak_to_partner")
    return targetCurrent(
      t,
      t.actorId === t.binding.actorId ? t.binding.pair!.groomId : t.binding.actorId,
    );
  const id = call.args.target_id;
  if (id === null) return call.name === "kill_vote" || call.name === "wedding_kill_vote";
  if (!targetCurrent(t, id)) return false;
  if (call.name === "choose_bridegroom") return id !== t.binding.actorId;
  if (call.name === "choose_wedding_witness")
    return id !== t.binding.actorId && id !== t.binding.pair!.groomId;
  const owner = t.binding.activeNight!.capture.owner;
  return owner === "pair"
    ? ![t.binding.actorId, t.binding.pair!.groomId].includes(id)
    : owner !== "witness" || id !== actorId;
}
export function weddingBrideState(world: World, actorId: number): GhostBrideState | null {
  const b = bindings.get(world);
  if (!b || actorId !== b.actorId) return null;
  if (!validBinding(b)) throw new Error("ghost_bride_authority_invalid");
  return readGhostBrideState(b.state);
}

const swallowedBadges = new WeakSet<World>();
export function weddingBadgeSwallowed(world: World): boolean {
  return swallowedBadges.has(world);
}
export function swallowWeddingBadges(
  world: World,
  events: import("../../../../core/domain").GameEvent[],
): void {
  const b = bindings.get(world);
  if (!b || !ghostBrideReady(world)) throw new Error("ghost_bride_badge_authority_invalid");
  swallowedBadges.add(world);
  for (const id of world.entityIds()) {
    const badge = world.getComponent(id, COMPONENT.Badge);
    const vote = world.getComponent(id, COMPONENT.VotingRight);
    if (badge) {
      if (badge.isSheriff && !badge.destroyed)
        events.push({
          timestamp: Date.now(),
          type: "sheriff_badge_destroyed",
          payload: { targetId: id, reason: "ghost_bride_single_wolf_blast" },
        });
      badge.isSheriff = false;
      badge.destroyed = true;
      badge.voteWeight = 1;
      delete badge.handoffPolicy;
    }
    if (vote) vote.weight = vote.canVote ? 1 : 0;
  }
}

/**
 * 负责鬼魂新娘原资源槽、参与者私态引用证据和安全审计数据的构造、读取及写入。
 * 输入为原角色／绑定上的数据字段与原编码函数；输出保留原槽引用、脱离的数据或原异常。
 * 公共字段与 schema 仍归共享契约；这里不持有 World、回合、婚约或第二份 live store。
 * 数据写入不授予选择许可；原生命、身份、请求和阶段复验仍由婚礼 authority 在原时点完成。
 * 写入失败保留已发生的字段前缀，取消只按原条件耗尽 remaining，不退款或修复被替换的槽。
 */
import { types } from "node:util";
import { freshGhostBrideState } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import type { GhostBrideState, WeddingPair } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import type { RoleInitializationComponent } from "../contracts";

// 同一原数据 reader：返回脱离副本／null，不能据此取得婚礼授权或原槽写权。
export { readGhostBrideState } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";

/** 这些字段继续放在原 Participant 上；引用证据与 JSON 内容证据分别核对，不建镜像。 */
export interface GhostBrideParticipantData {
  state: object;
  stateRefs: ReadonlyArray<readonly [string, unknown]>;
  initialPrivateState: unknown;
  expectedPrivateJson: string;
  auditPrivateJson: string;
}

interface GhostBrideResourceData {
  state: GhostBrideState;
}

/** 初始化先读取左侧 privateState，再调用原默认工厂；赋值失败不增加补偿。 */
export function initializeGhostBrideState(role: RoleInitializationComponent): void {
  role.privateState.ghostBride = freshGhostBrideState();
}

/** 仅原 own data／writable 检查；不额外拒绝 Proxy、校验 schema 或执行被替换的 getter。 */
export function ghostBrideStateWritable(state: object, key: string): boolean {
  const d = Object.getOwnPropertyDescriptor(state, key);
  return !!d && Object.hasOwn(d, "value") && d.writable === true;
}

/** 当前参与者原字段校验通过后才枚举引用并复制初态；完整阵容检查仍随后由 authority 执行，snapshot 保留原编码规则。 */
export function captureGhostBrideParticipantData(
  state: object,
  privateJson: string,
  snapshot: (value: unknown) => unknown,
): GhostBrideParticipantData {
  return {
    state,
    stateRefs: Object.entries(state),
    initialPrivateState: snapshot(state),
    expectedPrivateJson: privateJson,
    auditPrivateJson: privateJson,
  };
}

/** 原 Proxy 拒绝与 descriptor 捕获先于 World 身份查询；不执行容器 accessor。 */
export function ghostBridePrivateFields(p: GhostBrideParticipantData): PropertyDescriptorMap | null {
  if (types.isProxy(p.state)) return null;
  const fields = Object.getOwnPropertyDescriptors(p.state);
  return fields;
}

/** Role／privateState 原身份已核后才比较键数和各原字段引用；JSON 相等不足以续权。 */
export function ghostBridePrivateRefsCurrent(
  p: GhostBrideParticipantData,
  fields: PropertyDescriptorMap,
): boolean {
  return (
    Object.keys(fields).length === p.stateRefs.length &&
    p.stateRefs.every(
      ([k, v]) => fields[k] && Object.hasOwn(fields[k], "value") && fields[k]!.value === v,
    )
  );
}

/**
 * encoded 在原身体／身份复验之前形成，本命令只在复验通过后调用。
 * 设置期还须等于初始／已提交 JSON；其余时点允许原 nested 库存变化，逐参与者更新安全审计串。
 */
export function acceptGhostBrideParticipantAudit(
  p: GhostBrideParticipantData,
  encoded: string | null,
  setup: boolean,
): boolean {
  if (encoded === null || (setup && encoded !== p.expectedPrivateJson)) return false;
  p.auditPrivateJson = encoded;
  return true;
}

/** 原回执与关闭字段先处理，再到这里条件耗尽资源；两次 state 读取均保留原位置。 */
export function closeGhostBrideResource(b: GhostBrideResourceData): void {
  if (ghostBrideStateWritable(b.state, "remaining")) b.state.remaining = 0;
}

/** 原 pair 已冻结但尚未安装；先耗尽 remaining，再写 groomId，后写失败不撤销前写。 */
export function consumeGhostBrideChoice(b: GhostBrideResourceData, id: number): void {
  b.state.remaining = 0;
  b.state.groomId = id;
}

/** 两次 participants.get 与 JSON 的原顺序保留；婚约、Victory 与 status 均已由 authority 写完。 */
export function updateGhostBrideExpectedData(
  b: { participants: ReadonlyMap<number, GhostBrideParticipantData>; actorId: number },
  json: (value: unknown) => string | null,
): void {
  b.participants.get(b.actorId)!.expectedPrivateJson = json(
    b.participants.get(b.actorId)!.state,
  )!;
}

/** 失败审计仅在原身体／身份仍有效时调用；不可编码则保留该参与者最近的安全串。 */
export function refreshGhostBrideParticipantAudit(
  p: GhostBrideParticipantData,
  json: (value: unknown) => string | null,
): void {
  const encoded = json(p.state);
  if (encoded !== null) p.auditPrivateJson = encoded;
}

/** 新娘失败视图合成耗尽字段而不写槽；其他参与者解码安全串，groom 仍在该分支现场读取。 */
export function projectGhostBrideFailedPrivateData(
  b: { actorId: number; pair: Readonly<WeddingPair> | null },
  p: GhostBrideParticipantData,
  id: number,
): Record<string, unknown> {
  return id === b.actorId
    ? {
        ghostBride: {
          ...freshGhostBrideState(),
          remaining: 0,
          groomId: b.pair?.groomId ?? null,
        },
      }
    : (JSON.parse(p.auditPrivateJson) as Record<string, unknown>);
}

/**
 * 负责通过原婚礼 authority 顺序收集鬼魂新娘的新郎／见证人选择。
 * 输入为只读板子政策、当前阵容和引擎请求；输出为设置事实或中断结果，回合由原 owner 关闭。
 * 此协调器不改规则或绕过身份、失败及期限校验，每次请求保留原 new 点与 opaque turn。
 * 构造依赖只晚读实际类，base只传对象引用；内层turn与外层setup仍各按原 finally 关闭，不补交失败选择。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { GHOST_BRIDE_POLICY, readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import {
  Phase,
  type World,
  type GameEvent,
  type ActionProvider,
  type ActionStage,
  type ToolName,
} from "../../../../core/domain";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import {
  beginWeddingSetup,
  openWeddingTurn,
  closeWeddingTurn,
  closeWeddingSetup,
  ghostBrideReady,
  weddingSetup,
  weddingPair,
  weddingGroup,
  weddingActorView,
  weddingNightCapture,
  authorizedWeddingTurn,
  commitWeddingTool,
  takeWeddingChat,
} from "./authority";
/** 装配依赖晚提供类，每次仍 new 原参数的工厂；opaque 原回合仍由 authority 校验，不启用 fallback。 */
export async function executeWeddingTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  actorId: number;
  kind: "bridegroom" | "chat" | "witness" | "knife";
  tool: ToolName;
  stage: ActionStage;
  isCurrent: () => boolean;
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort };
}): Promise<void> {
  const { world, gateway, events, provider, day, actorId, kind, tool, stage, isCurrent } = input;
  const scope = openWeddingTurn(world, kind, actorId, day, isCurrent);
  try {
    const view = weddingActorView(world, actorId);
    // opaque turn 已开、原 view 已读后才查类；失败仍在原 try 内关闭此 turn。
    const request = new input.construction.requestFactory(world, events, day).create({
      phase: Phase.Night,
      actorId,
      allowedTools: [tool],
      stage,
      requiresAction: true,
      summary: { key: "request.summary.night_action" },
      context: {
        allow_fallback: false,
        action_failure_policy: "error",
        ...(kind === "witness" && view && "proposedWitnessId" in view
          ? { proposedWitnessId: view.proposedWitnessId }
          : {}),
      },
    });
    const raw = await provider.getAction(request);
    if (!authorizedWeddingTurn(world, actorId, Phase.Night, day, scope))
      throw new Error("ghost_bride_turn_revoked");
    const call = readWeddingTool(raw);
    if (!call || call.name !== tool) throw new Error("ghost_bride_required_action_missing");
    const valid = gateway.validateAndSanitize(world, actorId, call, {
      phase: Phase.Night,
      day,
      ghostBrideScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw new Error("ghost_bride_action_invalid");
    const committed = commitWeddingTool(scope, call);
    const pair = weddingPair(world);
    if (!pair) throw new Error("ghost_bride_pair_unavailable");
    if (kind === "bridegroom" && committed)
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_pair_chosen",
        payload: { ...pair },
        audience: Object.freeze([pair.brideId, pair.groomId].sort((a, b) => a - b)),
      });
    if (kind === "witness" && call.name === "choose_wedding_witness") {
      const votes = weddingSetup(world)!.witnessVotes;
      if (votes.some((v) => v.actorId === actorId && v.targetId === call.args.target_id))
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_witness_vote",
          payload: {
            policy: GHOST_BRIDE_POLICY,
            groupId: pair.groupId,
            day: 1,
            actorId,
            targetId: call.args.target_id,
            voteIndex: votes.length as 1 | 2,
          },
          audience: Object.freeze([]),
        });
      const group = weddingGroup(world);
      if (committed && group)
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_group_chosen",
          payload: { ...group },
          audience: Object.freeze(
            [group.brideId, group.groomId, group.witnessId].sort((a, b) => a - b),
          ),
        });
    }
    if (
      kind === "knife" &&
      committed &&
      (call.name === "kill_vote" || call.name === "wedding_kill_vote")
    ) {
      const capture = weddingNightCapture(world, day)!;
      if (capture.owner === "none") throw new Error("ghost_bride_knife_owner_invalid");
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_knife_vote",
        payload: {
          policy: GHOST_BRIDE_POLICY,
          groupId: pair.groupId,
          day,
          owner: capture.owner,
          actorId,
          targetId: call.args.target_id,
          abstain: call.args.abstain,
        },
        audience: Object.freeze(capture.owner === "ordinary_pack" ? [] : [actorId]),
      });
      if (capture.owner === "ordinary_pack")
        events.push({
          timestamp: Date.now(),
          type: "wolf_kill_vote_cast",
          payload: { actorId, targetId: call.args.target_id, abstain: call.args.abstain },
          audience: Object.freeze([...capture.actorIds].sort((a, b) => a - b)),
        });
    }
    const actualDisagreement =
      kind === "witness" &&
      call.name === "choose_wedding_witness" &&
      weddingSetup(world)!.witnessVotes.some(
        (v) => v.actorId === actorId && v.targetId === call.args.target_id,
      );
    const recordCommit = () =>
      safeRecordLogicOp({
        scope: "gateway",
        op: "validate_tool_call",
        actorId,
        phase: Phase.Night,
        status: "ok",
        input: { tool: call.name, args: call.args },
      });
    if (kind !== "chat" && (committed || actualDisagreement)) recordCommit();
    if (!committed) throw new Error("ghost_bride_action_commit_failed");
    if (kind === "chat") {
      const message = takeWeddingChat(scope);
      if (!message) throw new Error("ghost_bride_chat_delivery_revoked");
      recordCommit();
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_partner_chat",
        payload: { policy: GHOST_BRIDE_POLICY, groupId: pair.groupId, ...message },
        audience: Object.freeze([message.actorId, message.recipientId].sort((a, b) => a - b)),
      });
    }
  } finally {
    closeWeddingTurn(scope);
  }
}
export class GhostBrideSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    /** 保存引用；下方 base 的展开不会读取真正构造器。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (ghostBrideReady(this.world)) return true;
    const setup = weddingSetup(this.world);
    if (!setup || setup.status !== "pending" || day !== 1)
      throw new Error("ghost_bride_setup_unavailable");
    try {
      beginWeddingSetup(this.world, config, isCurrent);
      const base = {
        world: this.world,
        gateway: this.gateway,
        events: this.events,
        provider,
        day,
        isCurrent,
        // 普通数据字段仅传依赖对象；...base 不触发其 requestFactory getter。
        construction: this.construction,
      };
      await executeWeddingTurn({
        ...base,
        actorId: setup.actorId,
        kind: "bridegroom",
        tool: "choose_bridegroom",
        stage: "ghost_bride_groom",
      });
      const pair = weddingPair(this.world)!;
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "chat",
          tool: "speak_to_partner",
          stage: "ghost_bride_chat",
        });
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "witness",
          tool: "choose_wedding_witness",
          stage: "ghost_bride_witness",
        });
      if (!isCurrent() || !ghostBrideReady(this.world))
        throw new Error("ghost_bride_setup_revoked");
      return true;
    } finally {
      closeWeddingSetup(this.world, isCurrent() ? "failed" : "cancelled");
    }
  }
}

/**
 * 负责鬼魂新娘伴侣聊天及婚约狼刀请求。输入为绑定婚约夜、原参与者和已验证选择；输出为聊天结算、刀口与事实。
 * 婚约权威拥有原付款、投票和关闭；本阶段保 await 后真实复验，不令旧 pending 请求重新有效。
 * priority=150／400 的原顺序保持，过期普通／婚约狼刀清理归规则组合，历史票不重建或退款。
 */
import { StatusMark, COMPONENT } from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import type { NightStageHandler } from "../../stages/night/contracts";
import { executeWeddingTurn } from "./setup";
import {
  weddingPair,
  weddingNightCapture,
  resolveWeddingKnife,
  weddingKnifeCurrent,
} from "./authority";
export const WEDDING_CHAT_STAGE: NightStageHandler = {
  id: "ghost_bride_chat",
  priority: 150,
  async execute(ctx) {
    const day = ctx.currentDay(),
      pair = weddingPair(ctx.world);
    if (
      day === 1 ||
      !pair ||
      ![pair.brideId, pair.groomId].every(
        (id) => ctx.world.getComponent(id, COMPONENT.Alive)?.alive === true,
      )
    )
      return;
    for (const actorId of [pair.brideId, pair.groomId])
      await executeWeddingTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day,
        actorId,
        kind: "chat",
        tool: "speak_to_partner",
        stage: "ghost_bride_chat",
        isCurrent: ctx.isCurrent,
        construction: ctx,
      });
  },
};
export const WEDDING_KNIFE_STAGE: NightStageHandler = {
  id: "ghost_bride_knife",
  priority: 400,
  async execute(ctx) {
    const day = ctx.currentDay(),
      capture = weddingNightCapture(ctx.world, day);
    if (!capture) throw new Error("ghost_bride_capture_missing");
    for (const actorId of capture.actorIds) {
      const tool = capture.owner === "ordinary_pack" ? "kill_vote" : "wedding_kill_vote";
      await executeWeddingTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day,
        actorId,
        kind: "knife",
        tool,
        stage: capture.owner === "ordinary_pack" ? "wolf_vote" : "ghost_bride_knife",
        isCurrent: ctx.isCurrent,
        construction: ctx,
      });
      // 原投票仍由婚约权威保存，本阶段不从事实或目标重建票表。
    }
    const targetId = resolveWeddingKnife(ctx.world, day);
    ctx.events.push({
      timestamp: Date.now(),
      type: "ghost_bride_knife_resolved",
      payload: { ...capture, actorIds: [...capture.actorIds], targetId },
      audience: Object.freeze(
        capture.owner === "ordinary_pack" ? [] : [...capture.actorIds].sort((a, b) => a - b),
      ),
    });
    ctx.state.wolfTarget = targetId;
    if (targetId !== null && weddingKnifeCurrent(ctx.world, day, targetId)) {
      const marks = ctx.ensureMarks(targetId),
        life = ctx.world.getComponent(targetId, COMPONENT.Alive)!;
      marks.add(StatusMark.WolfKillMark);
      ctx.state.wolfTargetScope = { targetId, life, version: aliveLifeVersion(life)!, marks };
    }
  },
};

